// Triggers an immediate browser download for a generated file — no
// intermediate share sheet or extra tap, so choosing an export format
// downloads it right away.
export function downloadFile(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}
